--------------------------------------------------------------------------------
-- 04_xxfnd_triggers.sql
-- Row rules on common tables that are not covered by constraints.
-- (WHO and audit triggers are generated by XXFND_UTIL_PKG / XXFND_AUDIT_PKG.)
--------------------------------------------------------------------------------

-- Lookup customization level (EBS): S = values locked, E = values may be added
-- but not changed or deleted, U = fully editable. Applies to changes made in
-- the application; install scripts (no APEX session) are not restricted.
create or replace trigger xxfnd_lookup_values_lvl
    before insert or update or delete on xxfnd_lookup_values
    for each row
declare
    l_level xxfnd_lookup_types.customization_level%type;
begin
    if not xxfnd_util_pkg.in_apex_session then
        return;
    end if;
    select customization_level into l_level
      from xxfnd_lookup_types
     where lookup_type = coalesce(:new.lookup_type, :old.lookup_type);
    if l_level = 'S' then
        raise_application_error(-20130, 'Values of this lookup type are defined by the system and cannot be changed.');
    elsif l_level = 'E' and (deleting or (updating and (:new.lookup_code <> :old.lookup_code))) then
        raise_application_error(-20131, 'Values of this lookup type can be added or disabled, but not deleted or recoded.');
    end if;
end;
/
